function validate([operations, args]) {
  if (!Array.isArray(operations) || !Array.isArray(args) || operations.length !== args.length) return 'operations and arguments need the same length.';
  if (operations[0] !== 'FileSharing' || !Array.isArray(args[0]) || args[0].length !== 1) return 'Start with FileSharing(m).';
  const m = args[0][0];
  if (!Number.isInteger(m) || m < 1 || m > 100000) return 'm is a whole number from 1 to 10^5.';
  if (operations.length - 1 > 10000) return 'At most 10^4 calls to join, leave and request.';
  const active = new Set();
  for (let i = 1; i < operations.length; i++) {
    const a = args[i];
    if (!Array.isArray(a)) return 'Each call needs an argument list.';
    if (operations[i] === 'join') {
      const owned = a[0];
      if (a.length !== 1 || !Array.isArray(owned)) return 'join takes one list, ownedChunks.';
      if (owned.length > Math.min(100, m)) return 'ownedChunks has at most min(100, m) chunks.';
      if (owned.some(c => !Number.isInteger(c) || c < 1 || c > m)) return 'Chunk numbers go from 1 to m.';
      if (new Set(owned).size !== owned.length) return 'ownedChunks cannot repeat a chunk.';
      let id = 1;
      while (active.has(id)) id++;
      active.add(id);
    } else if (operations[i] === 'leave') {
      if (a.length !== 1 || !active.has(a[0])) return 'leave needs the id of a user currently in the system.';
      active.delete(a[0]);
    } else if (operations[i] === 'request') {
      if (a.length !== 2 || !active.has(a[0])) return 'request needs the id of a user currently in the system.';
      if (!Number.isInteger(a[1]) || a[1] < 1 || a[1] > m) return 'chunkID goes from 1 to m.';
    } else {
      return 'Only join, leave and request can follow the constructor.';
    }
  }
  return null;
}

