class FileSharing {
  constructor(m) {
    this.nextId = 1;
    this.freeIds = [];
    this.owners = new Map();
    this.chunksOf = new Map();
  }

  join(ownedChunks) {
    const userID = this.freeIds.length > 0 ? this.takeSmallestFreeId() : this.nextId++;
    this.chunksOf.set(userID, new Set(ownedChunks));
    for (const chunk of ownedChunks) {
      if (!this.owners.has(chunk)) {
        this.owners.set(chunk, new Set());
      }
      this.owners.get(chunk).add(userID);
    }
    return userID;
  }

  leave(userID) {
    for (const chunk of this.chunksOf.get(userID)) {
      this.owners.get(chunk).delete(userID);
    }
    this.chunksOf.delete(userID);
    this.releaseId(userID);
  }

  request(userID, chunkID) {
    const holders = this.owners.get(chunkID);
    if (!holders || holders.size === 0) {
      return [];
    }
    const result = [...holders].sort((a, b) => a - b);
    holders.add(userID);
    this.chunksOf.get(userID).add(chunkID);
    return result;
  }

  releaseId(id) {
    const heap = this.freeIds;
    heap.push(id);
    let i = heap.length - 1;
    while (i > 0 && heap[(i - 1) >> 1] > heap[i]) {
      const parent = (i - 1) >> 1;
      [heap[i], heap[parent]] = [heap[parent], heap[i]];
      i = parent;
    }
  }

  takeSmallestFreeId() {
    const heap = this.freeIds;
    const smallest = heap[0];
    const last = heap.pop();
    if (heap.length > 0) heap[0] = last;
    let i = 0;
    for (let child = 1; child < heap.length; child = 2 * i + 1) {
      if (child + 1 < heap.length && heap[child + 1] < heap[child]) child++;
      if (heap[i] <= heap[child]) break;
      [heap[i], heap[child]] = [heap[child], heap[i]];
      i = child;
    }
    return smallest;
  }
}

