function generate(rand, size) {
  const int = (low, high) => low + Math.floor(rand() * (high - low + 1));
  const large = size === 'large';
  const m = large ? [100000, 1000, int(5, 60)][int(0, 2)] : int(1, 6);
  const calls = large ? 499 : int(1, 12);
  const maxOwned = Math.min(m, large ? 30 : 4);
  const pickChunk = () => rand() < 0.7 ? int(1, Math.min(m, 40)) : int(1, m);
  const joinRate = 0.15 + rand() * 0.25;
  const leaveRate = 0.05 + rand() * 0.2;
  const active = new Set();
  const operations = ['FileSharing'];
  const args = [[m]];
  for (let i = 0; i < calls; i++) {
    const roll = rand();
    if (active.size === 0 || roll < joinRate) {
      const count = int(0, maxOwned);
      const owned = new Set();
      while (owned.size < count) owned.add(pickChunk());
      let id = 1;
      while (active.has(id)) id++;
      active.add(id);
      operations.push('join');
      args.push([[...owned]]);
    } else {
      const ids = [...active];
      const user = ids[int(0, ids.length - 1)];
      if (roll < joinRate + leaveRate) {
        active.delete(user);
        operations.push('leave');
        args.push([user]);
      } else {
        operations.push('request');
        args.push([user, pickChunk()]);
      }
    }
  }
  return [operations, args];
}
